WITH cd AS (SELECT CLIN_DRG_SK FROM wh.T_CLIN_DRG WHERE RXCUI = '897710'),
direct AS (
  SELECT d.AE_SK FROM wh.T_AE_DRG d WHERE d.CLIN_DRG_SK IN (SELECT CLIN_DRG_SK FROM cd)
),
harm AS (
  SELECT d.AE_SK FROM wh.X_AE_DRG_RXN x JOIN wh.T_AE_DRG d ON x.AE_DRG_SK = d.AE_DRG_SK
  WHERE x.CLIN_DRG_SK IN (SELECT CLIN_DRG_SK FROM cd)
)
SELECT COUNT(*) AS n FROM (SELECT AE_SK FROM direct UNION SELECT AE_SK FROM harm) u;

