input.query:
WITH s AS (
  SELECT subst_sk FROM wh.T_SUBST_MSTR WHERE UPPER(SUBST_NM) LIKE '%RIZATRIPTAN BENZOATE%'
  UNION
  SELECT x.SUBST_SK FROM wh.X_SALT_MOIETY x JOIN wh.T_SUBST_MSTR m ON m.SUBST_SK = x.MOIETY_SUBST_SK WHERE UPPER(m.SUBST_NM) LIKE '%RIZATRIPTAN BENZOATE%'
),
p AS (
  SELECT DISTINCT i.PRD_SK FROM wh.T_PRD_INGR i WHERE i.SUBST_SK IN (SELECT subst_sk FROM s)
)
SELECT COUNT(DISTINCT pk.LBLR_ORG_SK) AS firms, COUNT(DISTINCT p.PRD_SK) AS products, (SELECT string_agg(DISTINCT unii_cd || ':' || subst_nm, ' | ') FROM wh.T_SUBST_MSTR WHERE subst_sk IN (SELECT subst_sk FROM s)) AS substs
FROM p JOIN wh.T_PKG pk ON pk.PRD_SK = p.PRD_SK;

